"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["5090"],{23304(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.nao_permitido_fora_de_fonte_global","status":422,"titulo":"Valores de dom\xednio s\xf3 s\xe3o declarados no cat\xe1logo quando a fonte dos valores \xe9 global"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.nao_permitido_fora_de_fonte_global","requisitos":["UNI-REQ-0159"],"oQueAconteceu":["O fato indicado em `{id}` \xe9 categ\xf3rico, mas a origem das op\xe7\xf5es dele n\xe3o \xe9 global: as op\xe7\xf5es v\xeam do processo, das modalidades ofertadas, da geografia ou de outra fonte, e n\xe3o do pr\xf3prio cat\xe1logo. S\xf3 quando a origem \xe9 global os valores s\xe3o cadastrados no fato. A recusa vale para o acr\xe9scimo (`POST /api/configuracao/admin/fatos-candidato/{id}/valores`), para a corre\xe7\xe3o (`PUT .../valores/{codigo}`) e para a reordena\xe7\xe3o (`PUT .../ordem-dos-valores`).","A confer\xeancia do fato vem antes de qualquer confer\xeancia do corpo e, na corre\xe7\xe3o, antes da busca do valor: a recusa \xe9 esta mesmo que o `{codigo}` n\xe3o exista. A busca do fato vem primeiro: com um `{id}` que n\xe3o existe, a resposta \xe9 a de fato n\xe3o encontrado (`uniplus.configuracao.fato_candidato.nao_encontrado`). O fato de sistema \xe9 recusado antes, com `uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada`, o fato que n\xe3o \xe9 categ\xf3rico, com `uniplus.configuracao.fato_valor_dominio.nao_permitido_fora_de_categorico`, e o fato que resume respostas de grupo, com `uniplus.configuracao.fato_candidato.agregado_nao_tem_valores_proprios`: os valores do resumo de grupo s\xe3o os do fato de membro e s\xe3o mantidos nele. Nada \xe9 gravado."],"comoResolver":["As op\xe7\xf5es desse fato v\xeam da fonte que ele declara, e n\xe3o h\xe1 valor a cadastrar nele. Para cadastrar op\xe7\xf5es pr\xf3prias, altere a origem das op\xe7\xf5es do fato para global (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`, regra do UNI-REQ-0159) e cadastre os valores em seguida. A altera\xe7\xe3o \xe9 recusada quando deixaria inv\xe1lido algo do cadastro que j\xe1 usa o fato; nesse caso, cadastre um fato novo com a origem global."],"ondeAparece":["Acr\xe9scimo de um valor a um fato do cat\xe1logo","Corre\xe7\xe3o de um valor de um fato do cat\xe1logo","Reordena\xe7\xe3o dos valores de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);